window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["mcp-architecture"]={"title":"MCP 架构：让 Host 在隔离边界内连接外部能力","subtitle":"从 Host–Client–Server、JSON-RPC、能力协商与三类原语，理解 MCP 标准化了什么，以及授权与执行安全仍由谁负责。","thesis":"MCP 把 AI 应用与工具/数据源之间的连接从 M×N 个专用适配器变成共享协议；它规定通信和发现方式，却<b>不替 Host 替用户做信任、授权与副作用决策</b>。","quality":{"contractVersion":2,"examples":[{"section":4,"evidence":{"setup":"Client 从零连接天气 Server","rule":"若版本不兼容，Client 应断开","steps":"双方先 initialize，再确认 initialized、发现工具、由 Host 审批后调用","interpretation":"Host 把来源标记的结果作为不可信数据"}}],"formulas":[{"id":"mcp-total-latency","section":4,"formulaIndex":1,"symbols":[{"name":"T","meaning":"各阶段耗时以及它们构成的端到端总延迟","evidence":"总延迟由连接协商、发现、策略决策、工具执行和模型消费相加"}]}],"termReviews":[{"section":1,"reviewedAt":"2026-07-27","terms":[{"name":"MCP","meaning":"Host 与外部工具或数据能力之间的公共连接协议","purpose":"减少不同应用与提供方之间重复编写专用适配器","definitionEvidence":"MCP 是 Host 与外部能力之间的公共连接协议","purposeEvidence":"解决重复集成"}]},{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"Host","meaning":"持有用户会话、模型选择、同意和安全策略的 AI 应用","purpose":"统一协调不同 Server 并控制跨源上下文","definitionEvidence":"Host 持有用户目标与策略","purposeEvidence":"可隔离跨源上下文"},{"name":"Client","meaning":"由 Host 创建、只维护一个特定 Server 会话的协议端","purpose":"隔离各 Server 的能力目录和消息路由","definitionEvidence":"Client 只维护一个 Server 会话","purposeEvidence":"一对一会话表示通信边界"},{"name":"Server","meaning":"通过 MCP 暴露聚焦工具、资源或提示的服务程序","purpose":"让能力提供方用公共协议接入 Host","definitionEvidence":"Server 只接收完成请求所需的最少参数","purposeEvidence":"外部能力之间的公共连接协议"}]},{"section":3,"reviewedAt":"2026-07-27","terms":[{"name":"JSON-RPC","meaning":"用结构化请求、响应和通知交换远程方法消息的协议格式","purpose":"承载 MCP 数据层的方法和生命周期消息","definitionEvidence":"数据层规定 JSON-RPC 方法","purposeEvidence":"生命周期和原语"},{"name":"stdio","meaning":"通过本地进程标准输入输出交换协议消息的传输方式","purpose":"连接由 Host 启动的本地 Server","definitionEvidence":"stdio 或 HTTP 的连接","purposeEvidence":"本地进程与远端服务"}]},{"section":8,"reviewedAt":"2026-07-27","terms":[{"name":"幂等键","meaning":"让同一业务动作的重复请求只产生一次副作用的稳定标识","purpose":"避免响应丢失后的重试造成重复写入","definitionEvidence":"写操作先用幂等键","purposeEvidence":"工具已执行但响应丢了"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"MCP 是 Host 与外部能力之间的公共连接协议。","evidence":"MCP 是 Host 与外部能力之间的公共连接协议"},"problem":{"answer":"它解决不同应用与工具提供方重复集成的问题。","evidence":"解决重复集成"},"inputOutput":{"answer":"输入应用和提供方，输出统一生命周期消息。","evidence":"输入是不同 AI 应用和工具提供方，输出是统一的发现、调用、错误与生命周期消息"},"mechanism":{"answer":"共享协议把连接工作由近似乘积降为加和。","evidence":"从近似 M×N 降到 M+N"},"interpretation":{"answer":"收益是连接契约统一而非模型自动会用工具。","evidence":"协议只统一交换契约"},"boundary":{"answer":"它不保证兼容授权或调用决策。","evidence":"不保证 schema 永久兼容，也不决定模型是否应调用或用户是否授权"}},{"section":2,"definition":{"answer":"Host Client Server 是 MCP 的三层通信责任。","evidence":"输出 Host、Client、Server 三层责任"},"problem":{"answer":"它避免把会话连接与服务能力混成一个应用。","evidence":"为什么不能都叫“应用”"},"inputOutput":{"answer":"输入会话连接能力，输出三层责任与最少上下文。","evidence":"输入用户会话、单个连接和服务能力，输出 Host、Client、Server 三层责任"},"mechanism":{"answer":"Host 为每个 Server 建立隔离的一对一 Client。","evidence":"Client 只维护一个 Server 会话"},"interpretation":{"answer":"一对一会话表示通信边界而非信任结论。","evidence":"一对一会话表示通信边界"},"boundary":{"answer":"Server 不应默认读取完整对话。","evidence":"不表示 Server 已可信或可以读取完整对话"}},{"section":3,"definition":{"answer":"数据层定义消息语义，传输层负责具体连接。","evidence":"输出数据层语义与传输层风险"},"problem":{"answer":"它解释相同 MCP 方法为何仍有不同威胁。","evidence":"上层方法相同不代表风险相同"},"inputOutput":{"answer":"输入消息和连接方式，输出语义与传输风险。","evidence":"输入同一条协议消息和具体连接方式，输出数据层语义与传输层风险"},"mechanism":{"answer":"JSON-RPC 承载方法，stdio 或 HTTP 传输消息。","evidence":"数据层规定 JSON-RPC 方法"},"interpretation":{"answer":"连接成功只表示双方能通信。","evidence":"成功建立连接只证明双方能通信"},"boundary":{"answer":"本地和远端都须另做身份权限内容判断。","evidence":"都必须另做身份、权限和内容信任判断"}},{"section":4,"definition":{"answer":"初始化案例追踪版本协商发现审批调用和结果返回。","evidence":"完整示例：逐步追踪一次初始化与工具调用"},"problem":{"answer":"它说明 Client 从零连接到可检查结果的完整状态。","evidence":"到获得结果共经历哪些可检查状态"},"inputOutput":{"answer":"输入版本能力 schema，输出会话与天气结果。","evidence":"输入 Client/Server 版本、能力和天气工具 schema，输出协商后的会话与带来源的天气结果"},"mechanism":{"answer":"先初始化协商，再发现并由 Host 审批调用。","evidence":"双方先 initialize，再确认 initialized、发现工具、由 Host 审批后调用"},"interpretation":{"answer":"总延迟是五个阶段耗时之和。","evidence":"总延迟由连接协商、发现、策略决策、工具执行和模型消费相加"},"boundary":{"answer":"版本变化超时晚到会使缓存和盲重试不安全。","evidence":"版本变化、超时或晚到结果会使旧缓存和盲目重试不安全"}},{"section":5,"definition":{"answer":"Host 是跨 Server 协调和信任汇合点。","evidence":"由 Host 协调的隔离 Client 会话"},"problem":{"answer":"它防止不同 Server 直接获得跨源私有数据。","evidence":"避免 Server 彼此直连获得跨源数据"},"inputOutput":{"answer":"输入多个 Server 和上下文，输出隔离 Client 会话。","evidence":"输入多个 Server 及各自所需上下文，输出由 Host 协调的隔离 Client 会话"},"mechanism":{"answer":"Host 最小化传递信息并在本地汇合结果。","evidence":"Host 只向每个 Server 传最少信息并在本地汇合结果"},"interpretation":{"answer":"图中隔离表示设计责任而非协议强制保密。","evidence":"图中的隔离表示设计责任"},"boundary":{"answer":"共享凭据或完整会话仍会造成泄漏。","evidence":"协议本身不会阻止泄漏"}},{"section":6,"definition":{"answer":"Tools Resources Prompts 是控制主体不同的三类原语。","evidence":"输出由不同主体控制的操作"},"problem":{"answer":"它解决把全部 Server 内容当成同类输入的混淆。","evidence":"解决把所有 Server 内容都当成同一种模型输入的混淆"},"inputOutput":{"answer":"输入动作资源提示，输出相应受控操作。","evidence":"输入工具动作、上下文资源或可复用提示，输出由不同主体控制的操作"},"mechanism":{"answer":"模型提工具应用选资源用户选提示，Host 最终检查。","evidence":"模型提出 Tool，应用选择 Resource，用户选择 Prompt"},"interpretation":{"answer":"原语类别决定典型控制者与主要风险。","evidence":"三类 Server 原语的控制主体不同"},"boundary":{"answer":"任何原语仍可能越权过期或包含提示注入。","evidence":"任何原语仍可能越权、过期或包含提示注入"}},{"section":7,"definition":{"answer":"能力协商声明协议特性，授权裁决具体请求。","evidence":"能力协商输入双方支持的协议特性"},"problem":{"answer":"它防止把 tools 声明误当成全部工具权限。","evidence":"能力协商不是授权清单"},"inputOutput":{"answer":"输入特性或主体资源动作，输出方法集或允许决定。","evidence":"授权输入主体、资源、动作和作用域，输出某次请求是否允许"},"mechanism":{"answer":"Host 限制参数，Server 执行权威资源授权。","evidence":"Server 仍做权威资源授权"},"interpretation":{"answer":"声明 tools 只表示协议支持工具。","evidence":"声明 tools 只表示协议支持工具"},"boundary":{"answer":"它不能解释为所有用户可调用所有工具。","evidence":"不能解释为任意用户可以调用所有工具"}},{"section":8,"definition":{"answer":"恢复机制处理超时取消重连与副作用不确定性。","evidence":"输出重试、查询状态、取消或停止决定"},"problem":{"answer":"它避免响应丢失后盲重试造成重复写入。","evidence":"工具已执行但响应丢了"},"inputOutput":{"answer":"输入请求超时动作幂等副作用，输出恢复决定。","evidence":"输入请求 ID、超时、动作类型、幂等键和已知副作用，输出重试、查询状态、取消或停止决定"},"mechanism":{"answer":"读可重试，写先幂等或查状态，重连重新协商。","evidence":"读操作通常可重试，写操作先用幂等键或查询结果"},"interpretation":{"answer":"取消只表示 Host 不再等待。","evidence":"取消只表示 Host 不再等待"},"boundary":{"answer":"取消不能证明远端动作没有完成。","evidence":"不能证明远端动作没有完成"}},{"section":9,"definition":{"answer":"选型是在 MCP 直接 API 和内部函数之间分配连接责任。","evidence":"输出 MCP、直接 API 或内部函数方案"},"problem":{"answer":"它避免为追求标准化而包装每个内部函数。","evidence":"把每个函数都包装成 MCP Server 会更标准吗"},"inputOutput":{"answer":"输入复用发现延迟治理风险，输出连接方案。","evidence":"输入复用范围、发现需求、延迟、认证、治理成本和攻击面，输出 MCP、直接 API 或内部函数方案"},"mechanism":{"answer":"跨 Host 复用选 MCP，稳定热路径优先直接调用。","evidence":"跨 Host 生态复用最适合 MCP"},"interpretation":{"answer":"MCP 表示连接契约统一而非系统自动安全。","evidence":"采用 MCP 表示连接契约更统一"},"boundary":{"answer":"业务 API、SDK 和安全治理仍不可省略。","evidence":"不表示业务 API、SDK 或安全治理可以省略"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>画出 Host、Client、Server 与传输边界；手工追踪初始化和工具调用；区分 Tools、Resources、Prompts 的控制权；设计最小权限、超时与审计策略。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>协议解决的是复用，不是模型是否会调用工具<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">已有函数调用后，为什么还需要 MCP？</p><p>工具调用描述模型怎样产生结构化意图；MCP 描述应用怎样发现、读取和调用来自不同提供方的能力。没有公共协议，M 个 Host 对 N 个系统各写适配器，连接数量近似 M×N；协议让每个 Host 实现 Client、每个提供方实现 Server，主要工作更接近 M+N。</p><p>这不等于“写一次永远兼容”：schema、语义、权限与协议版本仍会变化。真正收益是把连接契约标准化，使发现、协商、错误、取消和审计有共同边界。</p><p>MCP 是 Host 与外部能力之间的公共连接协议，输入是不同 AI 应用和工具提供方，输出是统一的发现、调用、错误与生命周期消息。它把专用适配器数量从近似 M×N 降到 M+N，解决重复集成；协议只统一交换契约，不保证 schema 永久兼容，也不决定模型是否应调用或用户是否授权。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>三个角色与一对一会话<span class=\"dd-badge eng\">架构</span></h2><p class=\"dd-lead\">Host、Client、Server 为什么不能都叫“应用”？</p><p><b>Host</b> 是用户面对的 AI 应用，拥有完整会话、模型选择、用户同意和安全策略；它为每个 Server 创建一个 <b>Client</b>，Client 维护与该 Server 的专用会话并路由协议消息；<b>Server</b> 暴露聚焦的工具、资源或提示，可在本机进程或远端服务运行。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>角色</th><th>应知道什么</th><th>不应默认得到什么</th></tr></thead><tbody><tr><td>Host</td><td>用户目标、连接和策略</td><td>Server内部凭证</td></tr><tr><td>Client</td><td>单个Server的能力与会话</td><td>其他Server的私有上下文</td></tr><tr><td>Server</td><td>完成请求所需参数</td><td>完整对话与任意本机数据</td></tr></tbody></table></div><p>角色划分输入用户会话、单个连接和服务能力，输出 Host、Client、Server 三层责任：Host 持有用户目标与策略，Client 只维护一个 Server 会话，Server 只接收完成请求所需的最少参数。这样工作可隔离跨源上下文；一对一会话表示通信边界，不表示 Server 已可信或可以读取完整对话。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>数据层与传输层必须分开理解<span class=\"dd-badge eng\">分层</span></h2><p class=\"dd-lead\">stdio 和远程 HTTP 是两套 MCP 吗？</p><p>数据层定义 JSON-RPC 请求、响应、通知、生命周期和原语语义；传输层负责进程/网络连接、消息分帧与认证。stdio 常用于 Host 启动本地 Server；Streamable HTTP 适合远端服务。上层方法相同，不代表威胁相同：本地进程继承主机文件和环境风险，远程端增加网络身份、令牌、租户隔离和重放风险。</p><p>授权属于传输和应用安全的一部分；成功建立连接只证明双方能通信，不证明某个工具调用符合用户意图。</p><p>分层输入同一条协议消息和具体连接方式，输出数据层语义与传输层风险。数据层规定 JSON-RPC 方法、生命周期和原语，传输层负责 stdio 或 HTTP 的连接、分帧和认证；上层方法相同不代表风险相同。本地进程与远端服务都必须另做身份、权限和内容信任判断。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>完整示例：逐步追踪一次初始化与工具调用<span class=\"dd-badge math\">案例推演</span></h2><p class=\"dd-lead\">Client 从零连接天气 Server，到获得结果共经历哪些可检查状态？</p><ol class=\"dd-steps\"><li>Client 发送 <code>initialize</code>，声明支持的协议版本、Client 能力和实现信息。</li><li>Server 返回协商后的版本、<code>tools</code>/<code>resources</code> 等能力与实现信息；若版本不兼容，Client 应断开。</li><li>Client 发 <code>notifications/initialized</code>，双方进入正常操作期。</li><li>Client 调 <code>tools/list</code>，得到 <code>get_weather(city)</code> 的输入 schema。</li><li>模型提出 <code>{city:\"杭州\"}</code>；Host 做策略/同意检查后，Client 发 <code>tools/call</code>。</li><li>Server 返回内容或协议错误；Host 把来源标记的结果作为不可信数据交给模型，而非自动当指令执行。</li></ol><div class=\"dd-formula\" data-formula-id=\"mcp-total-latency\" data-display=\"mathml\"><math display=\"block\" aria-label=\"MCP 总延迟约等于连接协商、能力发现、策略决策、工具执行与模型消费时间之和\"><msub><mi>T</mi><mtext>总</mtext></msub><mo>≈</mo><msub><mi>T</mi><mtext>连接协商</mtext></msub><mo>+</mo><msub><mi>T</mi><mtext>发现</mtext></msub><mo>+</mo><msub><mi>T</mi><mtext>策略</mtext></msub><mo>+</mo><msub><mi>T</mi><mtext>工具</mtext></msub><mo>+</mo><msub><mi>T</mi><mtext>模型</mtext></msub></math></div><p>缓存工具列表可省发现时间，但收到列表变更通知或重新连接后必须按能力重建；请求超时后要取消并停止等待，避免幽灵结果晚到后触发重复动作。</p><p>初始化案例输入 Client/Server 版本、能力和天气工具 schema，输出协商后的会话与带来源的天气结果。双方先 initialize，再确认 initialized、发现工具、由 Host 审批后调用。总延迟由连接协商、发现、策略决策、工具执行和模型消费相加；缓存可省发现时间，但版本变化、超时或晚到结果会使旧缓存和盲目重试不安全。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：Host 是跨 Server 的唯一协调与信任汇合点<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">为什么 Server A 不该直接读取 Server B 或完整会话？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 320\" role=\"img\" aria-label=\"Host包含模型策略和两个相互隔离的Client分别连接本地和远程Server\"><defs><marker id=\"m27a\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"20\" y=\"35\" width=\"425\" height=\"250\" rx=\"14\" fill=\"#1b1f26\" stroke=\"#72b293\"/><text x=\"232\" y=\"64\" text-anchor=\"middle\" class=\"svg-t\">Host：用户同意 · 模型 · 策略 · 审计</text><rect x=\"48\" y=\"92\" width=\"155\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"125\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\">Client A</text><text x=\"125\" y=\"144\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">与 Server A 1:1</text><rect x=\"262\" y=\"92\" width=\"155\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"339\" y=\"120\" text-anchor=\"middle\" class=\"svg-t\">Client B</text><text x=\"339\" y=\"144\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">与 Server B 1:1</text><rect x=\"48\" y=\"194\" width=\"369\" height=\"60\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"232\" y=\"220\" text-anchor=\"middle\" class=\"svg-t\">Host 统一做跨源编排</text><text x=\"232\" y=\"242\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">只传最少必要上下文，不共享完整会话</text><path d=\"M203,127 L262,127\" stroke=\"#cf7c72\" stroke-dasharray=\"6 5\"/><text x=\"232\" y=\"116\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">隔离，不直连</text><path d=\"M125,92 L125,75\" stroke=\"#788293\"/><path d=\"M339,92 L339,75\" stroke=\"#788293\"/><path d=\"M203,127 L475,127\" stroke=\"#788293\" marker-end=\"url(#m27a)\"/><path d=\"M417,127 L475,230\" stroke=\"#788293\" marker-end=\"url(#m27a)\"/><rect x=\"480\" y=\"80\" width=\"225\" height=\"92\" rx=\"10\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"592\" y=\"109\" text-anchor=\"middle\" class=\"svg-t\">Server A · 本地文件</text><text x=\"592\" y=\"135\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">stdio · 进程与文件权限</text><text x=\"592\" y=\"155\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">Tools / Resources</text><rect x=\"480\" y=\"205\" width=\"225\" height=\"92\" rx=\"10\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"592\" y=\"234\" text-anchor=\"middle\" class=\"svg-t\">Server B · 远程工单</text><text x=\"592\" y=\"260\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">HTTP · 身份与租户边界</text><text x=\"592\" y=\"280\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">Tools / Prompts</text></svg><figcaption>图 1　协议连接可以复用，信任却不能传递；Host 必须保持连接隔离并控制上下文汇合。</figcaption></figure><p>架构图输入多个 Server 及各自所需上下文，输出由 Host 协调的隔离 Client 会话。Host 只向每个 Server 传最少信息并在本地汇合结果，避免 Server 彼此直连获得跨源数据。图中的隔离表示设计责任；若 Host 主动复制完整会话或共用凭据，协议本身不会阻止泄漏。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>三类 Server 原语的控制主体不同<span class=\"dd-badge eng\">原语</span></h2><p class=\"dd-lead\">Tools、Resources、Prompts 都是“给模型的东西”吗？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>原语</th><th>典型控制者</th><th>操作</th><th>主要风险</th></tr></thead><tbody><tr><td>Tools</td><td>模型提出、Host批准</td><td>发现并调用动作</td><td>副作用、参数与权限</td></tr><tr><td>Resources</td><td>应用选择</td><td>列出/读取上下文数据</td><td>越权读取、注入与过期</td></tr><tr><td>Prompts</td><td>用户选择</td><td>获取可复用模板</td><td>隐藏指令与版本漂移</td></tr></tbody></table></div><p>Server 还可能使用 Client 暴露的能力，例如 sampling、roots 或 elicitation；方向反转时信任也随之反转。Host 不能因为消息“来自 MCP”就跳过用户同意、输入校验或输出隔离。</p><p>三类原语输入工具动作、上下文资源或可复用提示，输出由不同主体控制的操作：模型提出 Tool，应用选择 Resource，用户选择 Prompt，Host 负责最终策略检查。它解决把所有 Server 内容都当成同一种模型输入的混淆；反向能力会反转信任方向，任何原语仍可能越权、过期或包含提示注入。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>能力协商不是授权清单<span class=\"dd-badge eng\">安全</span></h2><p class=\"dd-lead\">Server 声明 tools 能力，是否等于允许调用所有工具？</p><p>能力只说明协议特性可用，不说明具体主体可访问哪个资源。Host 应先校验 Server 身份和配置，再对工具逐项做允许列表、参数约束、用户/项目作用域和风险分级；Server 侧仍需执行真正的资源授权，不能信任 Client 传来的用户 ID。</p><p>本地 Server 使用最小进程权限和干净环境；远程 Server 使用短期、受众绑定的令牌。返回内容按不可信数据处理，尤其不能让资源文本或工具描述覆盖系统策略。</p><p>能力协商输入双方支持的协议特性，输出本次会话可使用的方法集合；授权输入主体、资源、动作和作用域，输出某次请求是否允许。Host 先验身份再逐工具限制参数，Server 仍做权威资源授权。声明 tools 只表示协议支持工具，不能解释为任意用户可以调用所有工具。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>失败恢复要覆盖超时、取消、重连与幂等<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">工具已执行但响应丢了，重试会发生什么？</p><p>读操作通常可安全重试；写操作必须携带幂等键或先查询状态。每个请求设置可配置超时，收到进度通知也保留最大时限；取消后 Server 应尽力终止，但 Host 仍要处理“动作完成、响应晚到”的不确定状态。</p><p>重连后重新协商版本和能力，不沿用旧会话假设。日志至少关联 Host 请求、Client 会话、Server 身份、工具、参数摘要、用户批准、结果和副作用 ID，才能定位错误发生在模型、Host、传输还是 Server。</p><p>恢复机制输入请求 ID、超时、动作类型、幂等键和已知副作用，输出重试、查询状态、取消或停止决定。读操作通常可重试，写操作先用幂等键或查询结果；重连后重新协商。取消只表示 Host 不再等待，不能证明远端动作没有完成，缺少状态查询时必须报告不确定。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>何时用 MCP，何时直接 API 或内部函数<span class=\"dd-badge eng\">选型</span></h2><p class=\"dd-lead\">把每个函数都包装成 MCP Server 会更标准吗？</p><p>跨多个 Host 复用、需要动态发现或第三方生态时，MCP 的契约价值最大；单进程内部稳定函数、极低延迟热路径或已有成熟服务 SDK 时，直接调用可能更简单。MCP 也不替代业务 API：Server 往往只是把已有 API 映射成面向 AI 应用的能力。</p><p>选型比较连接复用、版本治理、认证、可观测性、延迟和攻击面，不以“是否流行”决定。先做只读最小 Server，再逐步开放写工具。</p><p>选型输入复用范围、发现需求、延迟、认证、治理成本和攻击面，输出 MCP、直接 API 或内部函数方案。跨 Host 生态复用最适合 MCP，单进程稳定热路径常适合直接调用；先开放只读最小 Server，再按证据扩展写能力。采用 MCP 表示连接契约更统一，不表示业务 API、SDK 或安全治理可以省略。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">MCP 是协议边界，不是自动获得的安全边界。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>MCP 等于工具调用</td><td>前者连接生态，后者产生调用意图</td></tr><tr><td>连上 Server 就可信</td><td>连接、认证、授权与内容信任是不同判断</td></tr><tr><td>stdio 天然安全</td><td>本地进程可能拥有更大的文件与环境权限</td></tr><tr><td>能力协商就是权限</td><td>能力说明协议支持，权限约束具体主体与资源</td></tr><tr><td>协议会替我做重试</td><td>副作用幂等与业务恢复仍由应用设计</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>JSON-RPC、工具调用、认证与授权</td></tr><tr><td><b>本页核心</b></td><td>角色、分层、生命周期、能力协商、隔离</td></tr><tr><td>相邻</td><td>Agent循环、代码执行、提示注入</td></tr><tr><td>工程</td><td>幂等、取消、审计、版本兼容测试</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">11</span>先澄清：协议、SDK、Server 与 Agent 不是同一层<span class=\"dd-badge intuition\">概念消歧</span></h2><p class=\"dd-lead\">“装了一个 MCP”究竟可能指什么？</p><p>MCP 是消息与生命周期规范；SDK 是实现规范的代码库；Server 是暴露能力的运行程序；Agent 是决定是否以及怎样使用能力的应用逻辑。一个 Server 可以完全不含模型，一个 Agent 也可以不用 MCP 直接调用内部函数。把这些层混在一起，会把 SDK bug、协议不兼容、工具语义错误和模型决策错误统称为“MCP失败”，无法定位责任。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>MCP 标准化“怎样连接与交换”，不保证工具真实、安全、获准或适合当前任务。</div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>Host选择并信任一个Server</li><li>为Server创建隔离Client</li><li>协商版本与双向能力</li><li>发现原语并建立本地目录</li><li>模型提出或应用选择操作</li><li>Host授权后发送最小请求</li><li>验证结果并记录副作用</li><li>取消、重连或关闭会话</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>Client 与 Server 的关系是什么？</li><li>能力协商为何不等于授权？</li><li>Tools 与 Resources 的控制差别？</li><li>写工具超时后为何不能盲重试？</li><li>Server 返回文本为什么仍是不可信数据？</li><li>假设“MCP 架构：让 Host 在隔离边界内连接外部能力”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“MCP 架构：让 Host 在隔离边界内连接外部能力”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>每个Client维护与一个特定Server的一对一会话，由Host统一管理。</li><li>它只声明协议功能可用，不决定具体用户能访问的资源。</li><li>工具通常由模型提出调用，资源由应用选择进入上下文。</li><li>动作可能已完成，只是响应丢失，需要幂等键或状态查询。</li><li>协议保证消息结构，不保证内容真实或没有提示注入。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://modelcontextprotocol.io/specification/2025-06-18/architecture\" target=\"_blank\" rel=\"noopener\">MCP Architecture</a>：Host、Client、Server 与能力协商</li><li><a href=\"https://modelcontextprotocol.io/specification/2025-06-18/basic/lifecycle\" target=\"_blank\" rel=\"noopener\">MCP Lifecycle</a>：初始化、操作、超时与关闭</li><li><a href=\"https://modelcontextprotocol.io/docs/learn/architecture\" target=\"_blank\" rel=\"noopener\">MCP Architecture Overview</a>：数据层、传输层与原语</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
